from pathlib import Path
import base64, hashlib, json, zlib

path=Path('lib/main.dart')
body=path.read_text(encoding='utf-8')
expected_pre='88db87e85f2ad76f7eab770e45faea62a3d630d7295c4548695180e5ac25bfb6'
actual=hashlib.sha256(body.encode('utf-8')).hexdigest()
if actual!=expected_pre:
    # Responsive/security work legitimately changes the generated source hash.
    # Verify the v316 contract instead of rejecting a healthy evolved release.
    required=[
        'bridgepoint-v313-dna-data-tunnel-background',
        'bridgepoint-v313-responsive-action-rows',
        'bridgepoint-v314-investor-room',
        'bridgepoint-v315-catalog-package-fit',
        'bridgepoint-v316-manual-social-mode',
        'CUSTOMER PREVIEW',
        'NOAA LIVE RAIN RADAR',
    ]
    missing=[marker for marker in required if marker not in body]
    if missing:
        raise SystemExit(f'v318 release contract mismatch: hash {actual}; missing {missing}')
    print(f'v318 accepted evolved v316 baseline {actual} via release-contract verification')

blob=''
ops=json.loads(zlib.decompress(base64.b64decode(blob)).decode())
lines=body.splitlines(keepends=True)
for i1,i2,new_lines in reversed(ops):
    lines[i1:i2]=new_lines
body=''.join(lines)

expected_post='b15f69eb3c7fbe62af27b912809391fbdbcf04f3f9ae3e36f4ddbbc4c84b1255'
actual_post=hashlib.sha256(body.encode('utf-8')).hexdigest()
if actual_post!=expected_post:
    raise SystemExit(f'v318 output mismatch: expected {expected_post}, got {actual_post}')

for marker in [
    'bridgepoint_customer_access_contract_v318',
    '_RadarIntensityLegendV318',
    "if(_hasFeatureV318('weather_intelligence'))const _NavigationItem('Weather Center'",
    '_availablePackagesV318',
    'Live precipitation radar is not included in this account',
]:
    if marker not in body:
        raise SystemExit(f'v318 required marker missing: {marker}')

path.write_text(body,encoding='utf-8')
print('BRIDGEPOINT V318 ACCESS + WEATHER UI APPLIED')
print(' - customer navigation/package selector gated from server access contract')
print(' - live NOAA precipitation motion remains entitlement-gated')
print(' - radar reflectivity color/intensity legend added across weather map surfaces')
print(' - owner mode keeps full platform access')
